create policy family_consents_select on public.family_consents for select to authenticated
  using ((select app.active()) and (
      ((select app.is_staff()) and (select app.can_any(array['insured.read']::text[])))
      or ((select app.role()) = 'insured' and (owner_id = (select app.insured_id()) or viewer_id = (select app.insured_id())))
    ));
create policy family_consents_insert on public.family_consents for insert to authenticated
  with check ((select app.active()) and ((select app.role()) = 'insured' and (select app.can_any(array['family.self_service']::text[])) and (owner_id = (select app.insured_id()))));
create policy family_consents_update on public.family_consents for update to authenticated
  using ((select app.active()) and ((select app.role()) = 'insured' and (select app.can_any(array['family.self_service']::text[])) and (owner_id = (select app.insured_id()))))
  with check ((select app.active()) and ((select app.role()) = 'insured' and (select app.can_any(array['family.self_service']::text[])) and (owner_id = (select app.insured_id()))));
