-- family_requests: An employee asks to add a family member from the app; HR of the own company decides.
alter table public.family_requests enable row level security;
create policy family_requests_select on public.family_requests for select to authenticated
  using ((select app.active()) and (
      ((select app.is_staff()) and (select app.can_any(array['insured.read', 'policy_changes.decide', 'family.self_service', 'family.requests.decide']::text[])))
      or ((select app.role()) = 'hr' and (select app.can_any(array['insured.read', 'policy_changes.decide', 'family.self_service', 'family.requests.decide']::text[])) and (client_id = (select app.company_id())))
      or ((select app.role()) = 'insured' and (select app.can_any(array['insured.read', 'policy_changes.decide', 'family.self_service', 'family.requests.decide']::text[])) and (employee_id = (select app.insured_id())))
    ));
create policy family_requests_insert on public.family_requests for insert to authenticated
  with check ((select app.active()) and ((select app.role()) = 'insured' and (select app.can_any(array['family.self_service']::text[])) and (employee_id = (select app.insured_id()) and client_id = (select app.my_client_id()))));
create policy family_requests_update on public.family_requests for update to authenticated
  using ((select app.active()) and ((select app.role()) = 'hr' and (select app.can_any(array['family.requests.decide']::text[])) and (client_id = (select app.company_id()))))
  with check ((select app.active()) and ((select app.role()) = 'hr' and (select app.can_any(array['family.requests.decide']::text[])) and (client_id = (select app.company_id()))));
grant select (id, employee_id, client_id, full_name, birth_date, pinfl_hmac, pinfl_mask, relation, is_student, consent_at, status, created_at, decided_at, decided_by_id, decided_by_name, rejection_reason, policy_change_id, _pos, _created_at, _updated_at, _created_by) on public.family_requests to authenticated;
grant insert, update on public.family_requests to authenticated;

-- tasks: Requests between roles: MIG staff see the staff queues (and their own requests to HR); HR — requests to the own company.
alter table public.tasks enable row level security;
create policy tasks_select on public.tasks for select to authenticated
  using ((select app.active()) and (
      ((select app.is_staff()) and (select app.can_any(array['tasks.receive', 'tasks.ask']::text[])) and (to_role = (select app.role()) or created_by_id = (select app.uid()) or assignee_id = (select app.uid()) or to_role <> 'hr'))
      or ((select app.role()) = 'hr' and (select app.can_any(array['tasks.receive', 'tasks.ask']::text[])) and (to_role = 'hr' and client_id = (select app.company_id())))
    ));
create policy tasks_insert on public.tasks for insert to authenticated
  with check ((select app.active()) and (
      ((select app.is_staff()) and (select app.can_any(array['tasks.ask', 'tasks.request_hr']::text[])) and (created_by_id = (select app.uid())))
      or ((select app.role()) = 'hr' and (select app.can_any(array['tasks.ask', 'tasks.request_hr']::text[])) and (created_by_id = (select app.uid()) and client_id = (select app.company_id())))
    ));
create policy tasks_update on public.tasks for update to authenticated
  using ((select app.active()) and (
      ((select app.is_staff()) and (select app.can_any(array['tasks.receive', 'tasks.ask']::text[])) and (to_role = (select app.role()) or created_by_id = (select app.uid()) or assignee_id = (select app.uid()) or to_role <> 'hr'))
      or ((select app.role()) = 'hr' and (select app.can_any(array['tasks.receive', 'tasks.ask']::text[])) and ((to_role = 'hr' or created_by_id = (select app.uid())) and client_id = (select app.company_id())))
    ))
  with check ((select app.active()) and (
      ((select app.is_staff()) and (select app.can_any(array['tasks.receive', 'tasks.ask']::text[])) and (to_role = (select app.role()) or created_by_id = (select app.uid()) or assignee_id = (select app.uid()) or to_role <> 'hr'))
      or ((select app.role()) = 'hr' and (select app.can_any(array['tasks.receive', 'tasks.ask']::text[])) and ((to_role = 'hr' or created_by_id = (select app.uid())) and client_id = (select app.company_id())))
    ));
grant select, insert, update on public.tasks to authenticated;

-- notifications: In-app notifications: anyone may notify anyone (task done, request answered), only the addressee reads and marks them.
